-- MSIS-2402 — the course's 7-table OLTP dataset, for MySQL.
-- Generated from github/datasets/oltp_database/*.csv (same rows as the CSVs).
-- Usage:   mysql -u root < isba_shop_mysql.sql        (Windows: mysql -u root -p < isba_shop_mysql.sql)
-- Re-running it drops and rebuilds the isba_shop database from scratch.

DROP DATABASE IF EXISTS isba_shop;
CREATE DATABASE isba_shop;
USE isba_shop;

CREATE TABLE customers (
    customer_id  INT PRIMARY KEY,
    gender       VARCHAR(10) NOT NULL,
    country      VARCHAR(30) NOT NULL,
    segment      VARCHAR(30) NOT NULL,
    signup_date  DATE NOT NULL
);
CREATE TABLE products (
    product_id   INT PRIMARY KEY,
    category     VARCHAR(30) NOT NULL,
    price        DECIMAL(10,2) NOT NULL
);
CREATE TABLE stores (
    store_id     INT PRIMARY KEY,
    store_type   VARCHAR(20) NOT NULL,
    country      VARCHAR(30) NOT NULL
);
CREATE TABLE orders (
    order_id     INT PRIMARY KEY,
    customer_id  INT NOT NULL,
    store_id     INT NOT NULL,
    order_date   DATE NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (store_id)    REFERENCES stores(store_id)
);
CREATE TABLE order_items (
    order_item_id INT PRIMARY KEY,
    order_id      INT NOT NULL,
    product_id    INT NOT NULL,
    quantity      INT NOT NULL,
    category      VARCHAR(30) NOT NULL,
    price         DECIMAL(10,2) NOT NULL,
    sales_amount  DECIMAL(12,2) NOT NULL,
    FOREIGN KEY (order_id)   REFERENCES orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);
CREATE TABLE payments (
    payment_id     INT PRIMARY KEY,
    order_id       INT NOT NULL,
    payment_method VARCHAR(20) NOT NULL,
    payment_date   DATE NOT NULL,
    payment_amount DECIMAL(12,2) NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);
CREATE TABLE shipments (
    shipment_id   INT PRIMARY KEY,
    order_id      INT NOT NULL,
    carrier       VARCHAR(20) NOT NULL,
    shipment_date DATE NOT NULL,
    delivery_date DATE NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);


-- customers: 1000 rows

-- products: 2000 rows

-- stores: 50 rows

-- orders: 100000 rows

-- order_items: 300000 rows

-- payments: 100000 rows

-- shipments: 100000 rows

-- Row counts should be: customers 1000, products 2000, stores 50, orders 100000,
-- order_items 300000, payments 100000, shipments 100000.
SELECT 'customers' AS tbl, COUNT(*) AS n FROM customers UNION ALL
SELECT 'products', COUNT(*) FROM products UNION ALL
SELECT 'stores', COUNT(*) FROM stores UNION ALL
SELECT 'orders', COUNT(*) FROM orders UNION ALL
SELECT 'order_items', COUNT(*) FROM order_items UNION ALL
SELECT 'payments', COUNT(*) FROM payments UNION ALL
SELECT 'shipments', COUNT(*) FROM shipments;
